; sine.asm -- chapter 13: a curve drawn with three tables
; generated by gen13.py
        INCLUDE "msx.inc"
        OUTPUT "sine.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
LINES   EQU $D000               ; the second table, made by mklines
; A curve drawn with three tables: the height of the curve for each column,
; worked out in Python when this file was written, since the Z80 has no
; sine; the address of each pixel line; and the bit of each of the eight
; pixels in a byte (figure 13.2).
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        call mklines
        ld e, 0                 ; E: x, 0 to 255
sn1:    ld l, e
        ld h, high sines
        ld a, (hl)              ; y, from the first table
        ld l, a
        ld h, high LINES
        ld c, (hl)
        inc h
        ld b, (hl)              ; BC: line y, from the second
        ld a, e
        and %11111000           ; eight bytes to a cell across
        add a, c
        ld c, a                 ; BC: the byte
        ld a, e
        and %00000111
        ld l, a
        ld h, high masks
        ld d, (hl)              ; D: the pixel's bit, from the third
        call vor                ; the pixel set
        inc e
        jr nz, sn1
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; vor: the byte at BC in the VRAM ORed with D: read through the ports,
;      changed, and written back (chapter 19). Display off. Uses A.
vor:    ld a, c
        out (VDP_CTRL), a
        ld a, b
        out (VDP_CTRL), a       ; the address, to read
        in a, (VDP_DATA)
        or d
        push af
        ld a, c
        out (VDP_CTRL), a
        ld a, b
        or $40
        out (VDP_CTRL), a       ; the same address, to write
        pop af
        out (VDP_DATA), a
        ret

; mklines: the address in Graphic II's patterns of each pixel line, 0 to 191,
;          into two tables: low bytes at LINES + y, high bytes one page on.
;          Uses A, DE, HL.
mklines:
        ld e, 0                 ; E: y
ml1:    ld a, e
        call calc               ; HL: line y's address, worked out
        ld d, high LINES
        ld a, l
        ld (de), a              ; the low byte
        inc d
        ld a, h
        ld (de), a              ; the high byte, a page on
        inc e
        ld a, e
        cp 192
        jr nz, ml1
        ret

; calc: HL = the address of pixel line A (0-191) in Graphic II's patterns, at
;       the left edge: the row of cells times 256, and the line in the cell.
;       Uses A, D.
calc:   ld d, a                 ; y, kept
        and %00000111
        ld l, a                 ; the line in the cell
        ld a, d
        rrca
        rrca
        rrca
        and %00011111
        ld h, a                 ; the row of cells, times 256
        ret

        ALIGN 256               ; each table a page of its own
sines:
        db 96, 94, 92, 90, 87, 85, 83, 81, 79, 77, 75, 73, 70, 68, 66, 64
        db 62, 60, 58, 56, 55, 53, 51, 49, 47, 45, 44, 42, 40, 39, 37, 35
        db 34, 32, 31, 29, 28, 27, 25, 24, 23, 22, 21, 19, 18, 17, 16, 16
        db 15, 14, 13, 12, 12, 11, 11, 10, 10, 9, 9, 9, 8, 8, 8, 8
        db 8, 8, 8, 8, 8, 9, 9, 9, 10, 10, 11, 11, 12, 12, 13, 14
        db 15, 16, 16, 17, 18, 19, 21, 22, 23, 24, 25, 27, 28, 29, 31, 32
        db 34, 35, 37, 39, 40, 42, 44, 45, 47, 49, 51, 53, 55, 56, 58, 60
        db 62, 64, 66, 68, 70, 73, 75, 77, 79, 81, 83, 85, 87, 90, 92, 94
        db 96, 98, 100, 102, 105, 107, 109, 111, 113, 115, 117, 119, 122, 124, 126, 128
        db 130, 132, 134, 136, 137, 139, 141, 143, 145, 147, 148, 150, 152, 153, 155, 157
        db 158, 160, 161, 163, 164, 165, 167, 168, 169, 170, 171, 173, 174, 175, 176, 176
        db 177, 178, 179, 180, 180, 181, 181, 182, 182, 183, 183, 183, 184, 184, 184, 184
        db 184, 184, 184, 184, 184, 183, 183, 183, 182, 182, 181, 181, 180, 180, 179, 178
        db 177, 176, 176, 175, 174, 173, 171, 170, 169, 168, 167, 165, 164, 163, 161, 160
        db 158, 157, 155, 153, 152, 150, 148, 147, 145, 143, 141, 139, 137, 136, 134, 132
        db 130, 128, 126, 124, 122, 119, 117, 115, 113, 111, 109, 107, 105, 102, 100, 98
        ALIGN 256
masks:  db $80, $40, $20, $10, $08, $04, $02, $01
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
